typedef struct {
    uint8_t nin, nout, npar;
    uint8_t fixed_inputs;    /* inputs with independently switchable parameter links */
    int8_t cvbase;          /* index of the p1 input (p2 follows), -1: the module has no parameter inputs */
    int8_t thru;            /* the input a bypassed module passes to all of its outputs, -1: they are silent */
    uint8_t ndata;          /* bytes the record carries after the parameters and pins (a Steps module: name + pattern) */
    uint16_t aout;          /* the audio outputs (bit i: output i), which a paraphonic group's mix weighs (engine.c para_w) */
    const int32_t *pmin, *pmax, *pdef, *pinc;   /* Q16.16; pinc: what one knob click adds */
    const char *name;       /* upper case, for the LCD */
    const char *const *pname;
    const char *const *inname;              /* input names, upper case */
    const uint8_t *plog;                    /* 1: a logarithmic parameter, 2: logarithmic and bent (the filter cutoff) */
    const char *const *punit;               /* "HZ", "ST", ... or "" */
    const char *const *const *pchoice;      /* per parameter: the names of a choice parameter (0-terminated), or 0 */
    const int32_t *ptop;    /* Q16.16, or 0: past pmax, the most the knobs and a stored value reach (ParamDef.top) */
    const uint8_t *psince;  /* or 0: per parameter the patch format that appended it (ParamDef.since; 0 = older): a binary of an
                             * older format holds fewer (engine.c eng_npar) */
} def_t;
/* the most parameter j of def d takes: its stretch past pmax (ptop), else pmax */
#define DEF_TOP(d, j) ((d)->ptop ? (d)->ptop[j] : (d)->pmax[j])

